class Solution {
    private int factor(int value,int divisor){
        int count=0;
        while(value%divisor==0){
            count++;
            value/=divisor;
        }
        return count;
    }
    public int maxTrailingZeros(int[][] grid){
        int rows=grid.length,columns=grid[0].length;
        int[][] two=new int[rows][columns],five=new int[rows][columns],rowTwo=new int[rows][columns+1],rowFive=new int[rows][columns+1],columnTwo=new int[rows+1][columns],columnFive=new int[rows+1][columns];
        for(int r=0;r<rows;r++)for(int c=0;c<columns;c++){
            two[r][c]=factor(grid[r][c],2);
            five[r][c]=factor(grid[r][c],5);
            rowTwo[r][c+1]=rowTwo[r][c]+two[r][c];
            rowFive[r][c+1]=rowFive[r][c]+five[r][c];
            columnTwo[r+1][c]=columnTwo[r][c]+two[r][c];
            columnFive[r+1][c]=columnFive[r][c]+five[r][c];
        }
        int answer=0;
        for(int r=0;r<rows;r++)for(int c=0;c<columns;c++){
            int[] horizontalTwo={
                rowTwo[r][c+1],rowTwo[r][columns]-rowTwo[r][c]
            };
            int[] horizontalFive={
                rowFive[r][c+1],rowFive[r][columns]-rowFive[r][c]
            };
            int[] verticalTwo={
                columnTwo[r+1][c],columnTwo[rows][c]-columnTwo[r][c]
            };
            int[] verticalFive={
                columnFive[r+1][c],columnFive[rows][c]-columnFive[r][c]
            };
            for(int h=0;h<2;h++)for(int v=0;v<2;v++)answer=Math.max(answer,Math.min(horizontalTwo[h]+verticalTwo[v]-two[r][c],horizontalFive[h]+verticalFive[v]-five[r][c]));
        }
        return answer;
    }
}

